<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Services\ElectionService;$user=Authorization::requireRoles(['admin','organizer']);$id=(int)($_GET['id']??0);$election=ElectionService::find($id);if(!$election||!Authorization::canManageElection($user,(int)$election['organization_id'])){http_response_code(404);exit('Votación no encontrada.');}$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::validate($_POST['_csrf']??null)){$error='Solicitud inválida.';}else{try{$action=(string)($_POST['action']??'');if($action==='add_question')ElectionService::addQuestion($id,$_POST);if($action==='delete_question')ElectionService::deleteQuestion($id,(int)($_POST['question_id']??0));if($action==='status')ElectionService::setStatus($id,(string)($_POST['status']??''));header('Location: /election.php?id='.$id.'&ok=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}}$election=ElectionService::find($id);$questions=ElectionService::questions($id);$editable=in_array($election['status'],['draft','scheduled'],true)&&empty($election['ballot_locked_at']);$statusClass=$election['status']==='open'?'v-status-open':($election['status']==='closed'?'v-status-closed':'v-status-draft');
